from pathlib import Path
import sys
sys.path.insert(0,str(Path(__file__).resolve().parent.parent))
from rendu import outils
base,p,c,h,w,table,liste,save=outils(2,6)
t=p('L’examen commence par le profil attendu : dans une présentation compatible avec la fibromyalgie, la HAS ne décrit ni déficit moteur ou sensitif systématisé ni gonflement articulaire observable. Une hypersensibilité musculaire, tendineuse ou articulaire peut néanmoins être présente ; la normalité structurelle ne signifie donc pas l’absence de douleur.','f83-has-orientation')
t+=p('La consultation associe l’entretien à un examen en présentiel lorsque cela est possible. Un formulaire rempli seul ne remplace pas l’appréciation clinique, la recherche d’un diagnostic concurrent ni l’examen nécessaire à une anomalie nouvelle.','f83-has-evaluation','f83-rcp-consultation')
t+=h('Cartographie et région axiale : comparer le récit au schéma corporel')
t+=p('Le clinicien fait préciser les régions douloureuses au-delà du site dominant et les reporte sur une carte corporelle. Il distingue la distribution axiale de celles des membres et conserve les localisations nécessaires au WPI, car le critère de généralisation n’utilise pas exactement tous les mêmes sites.','f83-rcp-symptomes','f83-rcp-annexe2016')
t+=p('Une douleur rachidienne avec déficit moteur ou symptômes sphinctériens impose la voie neurologique urgente. L’examen ne cherche alors pas à accumuler des points de sensibilité ; il sert à reconnaître une compression nécessitant imagerie et avis spécialisé immédiats.','pa17-lomb22-queue','pa17-lomb22-urgence')
t+=h('Membres et mains : rechercher une anomalie objectivable')
t+=p('Pour les mains, le support technique HUG décrit une inspection de la peau, des ongles, des tuméfactions, des épaississements et des déformations. Ce geste fournit une recherche concrète d’anomalies locales ; il ne transforme pas une déformation ou une tuméfaction en signe de fibromyalgie.','oa82-hug-inspection','f83-has-orientation')
t+=p('La palpation de la capsule vise à détecter une synovite ou un épanchement. Pour les petites articulations, une pression régulière du côté palmaire, notamment en flexion, déplace les tissus ou le liquide vers les doigts placés dorsalement ; une douleur diffuse de pression seule ne démontre pas un épanchement.','oa82-hug-palpation','f83-has-orientation')
t+=p('L’examen fonctionnel du poignet explore flexion, extension et inclinaisons ulnaire et radiale ; la prono-supination implique aussi le coude. Pour les doigts, la distance pulpe-paume ou la position du prieur permet de documenter la mobilité, sans inventer une amplitude normale chiffrée absente du passage technique.','oa82-hug-mobilite')
t+=h('Force : établir le normal avant de qualifier la faiblesse')
f=w('Force musculaire : geste et cotation',[
('La force normale correspond à une opposition à une résistance extérieure importante et reçoit la cotation 5 dans le support HUG. Le clinicien distingue les mouvements contre la pesanteur puis contre résistance, au lieu de confondre une plainte de fatigue avec une parésie démontrée.',['oa82-hug-force']),
('La cotation 4 correspond au mouvement contre pesanteur et résistance ; 3 correspond au mouvement contre la pesanteur ; 2 correspond au mouvement possible seulement sans pesanteur. La cotation 1 décrit une contraction sans mouvement articulaire et 0 l’absence de contraction visible.',['oa82-hug-force']),
('La force de préhension constitue un exemple d’évaluation fonctionnelle des petites articulations. Une diminution peut aussi résulter de synovite, d’une affection musculo-tendineuse, d’une radiculopathie ou d’une neuropathie ; le résultat doit donc être interprété dans son contexte.',['oa82-hug-force'])])
t+=p('Le clinicien documente la force par le geste décrit dans '+f+'. Une anomalie objective conduit à une exploration orientée, car la DGN recommande notamment de penser à une myopathie devant parésie, atrophie ou CK élevées.','oa82-hug-force','p83-myofascial-fibro')
t+=h('Sensibilité : décrire le phénomène sans fabriquer un test décisif')
t+=p('La palpation peut révéler une hypersensibilité à la pression et le récit peut rapporter une sensibilité à des stimulations ordinaires. Le RCP relie cette constatation au traitement sensoriel de la douleur ; elle constitue un élément du syndrome mais pas un biomarqueur spécifique.','f83-rcp-symptomes','f83-rcp-mecanismes','p83-myofascial-fibro')
t+=p('Le clinicien recherche séparément un déficit sensitif systématisé, puisque son absence appartient au profil clinique habituel décrit par la HAS. Une anomalie territoriale ne se résume pas à l’hypersensibilité diffuse et justifie les explorations ciblées selon le contexte.','f83-has-orientation','f83-has-depistage')
t+=table(['Constat normal ou compatible','Geste utile','Anomalie qui change la suite'],[
[p('La plainte de fatigue peut exister avec une force conservée.','f83-rcp-definition','f83-has-orientation'),p('Le clinicien teste les mouvements contre pesanteur et résistance et note la force.','oa82-hug-force'),p('Une parésie ou une atrophie oriente vers une maladie neuromusculaire à explorer.','p83-myofascial-fibro')],
[p('Une hypersensibilité peut coexister avec l’absence de gonflement observable.','f83-has-orientation'),p('Le clinicien inspecte puis palpe la capsule lorsqu’une articulation est suspecte.','oa82-hug-inspection','oa82-hug-palpation'),p('Une synovite ou un épanchement impose une démarche articulaire spécifique.','oa82-hug-palpation','f83-has-depistage')],
[p('Les symptômes peuvent varier entre les consultations.','f83-rcp-fluctuation'),p('Le clinicien compare la distribution rapportée et répète l’examen approprié à un symptôme nouveau.','f83-rcp-symptomes','f83-has-differentiel'),p('Une anomalie nouvelle exige une recherche causale avant son attribution à la fibromyalgie.','f83-has-differentiel')]])
t+=p('Avant un programme d’activité physique, l’évaluation peut être complétée par un bilan de mobilité, force, souplesse, équilibre, capacité aérobie et fatigabilité. La HAS demande que les symptômes ressentis pendant et après l’évaluation orientent la prescription, avec des objectifs réalistes et des activités tolérées.','f83-has-programme')
save(t)

base,p,c,h,w,table,liste,save=outils(2,7)
t=p('L’approche syndromique regroupe les manifestations utiles à la consultation sans créer des stades nouveaux. Le clinicien sépare les symptômes rapportés des signes observables et conserve les diagnostics concomitants lorsque des anomalies dépassent le profil habituel.','f83-rcp-definition','f83-has-orientation','f83-has-depistage')
t+=h('7.1 — Syndrome douloureux généralisé avec hypersensibilité')
f=w('Douleur étendue et hypersensibilité : définition et recherche',[
('La douleur étendue concerne plusieurs régions du corps ; le clinicien demande explicitement les autres localisations lorsque seule une région est spontanément rapportée. Une carte corporelle aide à documenter cette distribution.',['f83-rcp-symptomes']),
('L’hypersensibilité se manifeste notamment par une douleur à la pression ou une réponse excessive à des stimulations ordinaires. La palpation peut constater une sensibilité diffuse, tandis que l’entretien recherche les sensibilités au toucher, au froid, à la chaleur, à la lumière ou au bruit.',['f83-rcp-symptomes','f83-has-orientation']),
('Le mécanisme dominant proposé concerne une modulation sensorielle modifiée dans les systèmes périphériques et centraux. La constatation ne prouve ni une lésion musculaire inflammatoire ni une neuropathie chez chaque patient.',['f83-rcp-mecanismes','p83-myofascial-fibro'])])
t+=p('Les signes fonctionnels comprennent des douleurs persistantes, souvent variables en intensité et en site ; le signe physique compatible est une hypersensibilité sans déficit systématisé ni gonflement observable. La fenêtre '+f+' précise leur recherche et leur portée.','f83-has-orientation')
t+=h('7.2 — Fatigue intrusive et difficultés cognitives')
f=w('Fatigue et brouillard cognitif : définition et recherche',[
('La fatigue intrusive peut être physique, avec baisse d’énergie ou épuisement, cognitive, avec difficulté à se concentrer ou à se souvenir, et émotionnelle, avec réduction de la motivation. L’entretien précise le retentissement de chacune plutôt que d’assimiler toute fatigue à une dépression.',['f83-rcp-symptomes']),
('Le score de sévérité interroge la fatigue et les difficultés de pensée ou de mémoire durant la semaine écoulée. Cette appréciation symptomatique ne remplace pas l’examen de la force lorsqu’une faiblesse est rapportée.',['f83-rcp-sss','oa82-hug-force']),
('Une parésie, une atrophie ou une anomalie biologique impose une analyse neuromusculaire indépendante. Le mécanisme nociplastique ne fournit pas une explication automatique à tous les déficits observés.',['p83-myofascial-fibro','f83-has-depistage'])])
t+=p('Les signes fonctionnels sont l’épuisement et les difficultés de concentration ou de mémoire ; aucun signe moteur spécifique n’est exigé pour les confirmer. Le clinicien documente la plainte avec '+f+' et examine séparément une faiblesse objective.','f83-rcp-definition','f83-has-orientation','oa82-hug-force')
t+=h('7.3 — Sommeil non réparateur et troubles associés')
f=w('Sommeil non réparateur : définition et recherche',[
('Le sommeil non réparateur correspond au sentiment de ne pas être reposé au réveil. Le clinicien précise qualité, quantité, habitudes et médicaments pouvant perturber le sommeil, puis recherche une insomnie ou une affection spécifique.',['f83-rcp-alerte','f83-has-sommeil']),
('Devant cette plainte, la HAS recommande de rechercher des signes d’apnées du sommeil ou de syndrome des jambes sans repos et, lorsque ces diagnostics sont confirmés, de proposer leur traitement propre. Le symptôme ne doit donc pas être absorbé sans examen dans une seule étiquette de fibromyalgie.',['f83-has-sommeil']),
('Le lien avec fatigue, douleur et humeur justifie une prise en charge coordonnée. Les habitudes de veille et de sommeil et les traitements sont réévalués dans la durée.',['f83-has-sommeil','f83-has-humeur'])])
t+=p('Le signe fonctionnel est le réveil non réparateur, éventuellement associé à une insomnie ; un signe physique spécifique de fibromyalgie n’est pas requis dans ce domaine. La fenêtre '+f+' explique pourquoi le clinicien recherche des affections du sommeil traitables.','f83-rcp-definition','f83-has-sommeil')
t+=h('7.4 — Retentissement émotionnel, fonctionnel et social')
f=w('Détresse et participation : définition et recherche',[
('La détresse, les difficultés d’activités et les modifications des relations font partie de l’évaluation biopsychosociale. Le clinicien interroge ce qui a changé dans le quotidien, les rôles familiaux, le travail et les liens sociaux.',['f83-rcp-bps','f83-has-evaluation']),
('Une anxiété ou une dépression peut coexister et mérite une évaluation et un traitement propres. Le clinicien ne présente pas ces troubles comme la preuve d’une cause psychologique de la douleur.',['f83-has-humeur','f83-rcp-mecanismes']),
('L’idéation suicidaire modifie immédiatement la conduite : la HAS demande une orientation psychiatrique sans tarder. La surveillance de l’humeur demeure nécessaire au fil du suivi et lors des traitements antidépresseurs.',['f83-has-humeur','aips-f83-dulox-surveillance'])])
t+=p('Les signes fonctionnels comprennent les difficultés à participer aux activités et les symptômes émotionnels rapportés ; l’entretien les analyse avec '+f+'. L’examen et les questionnaires évaluent leur portée sans inventer un signe physique pathognomonique.','f83-has-evaluation','f83-has-humeur','f83-rcp-criteres-cadre')
t+=table(['Syndrome','Signes fonctionnels','Signes physiques et limite'],[
['Douleur généralisée',p('Le patient rapporte plusieurs sites douloureux et des fluctuations.','f83-has-orientation'),p('Une hypersensibilité est compatible ; un déficit systématisé ou une synovite conduit à une autre recherche.','f83-has-orientation')],
['Fatigue et cognition',p('Le patient décrit épuisement, concentration ou mémoire gênées.','f83-rcp-symptomes'),p('La force est examinée séparément ; une parésie objectivée oriente la démarche neuromusculaire.','oa82-hug-force','p83-myofascial-fibro')],
['Sommeil',p('Le réveil peut rester non réparateur.','f83-rcp-alerte'),p('Le clinicien recherche les affections spécifiques évoquées par l’entretien et leurs éléments diagnostiques propres.','f83-has-sommeil')],
['Participation et humeur',p('Les activités, relations et capacités professionnelles peuvent être altérées.','f83-has-evaluation'),p('Aucun signe somatique isolé ne confirme ce retentissement ; l’évaluation clinique et les outils partagés guident le suivi.','f83-has-suivi')]])
save(t)
